import {LIFE_ACTIVITIES,HOUSEHOLD,LIFE_UPGRADES,tapValue,focusPenalty,SEARCH_SPOTS,offerFor,foundItems} from './life.mjs';
import {PROPERTIES,FOUNDERS,HUSTLES,COURSES,PRODUCTS,DILIGENCE,CAFE_STYLES} from './content.mjs';
import {initial,freshInitial,action,forecast,worth,stage,stageName,nextGoal,valuation,BILLING,CAREERS,ECONOMICS,startupCost,OPERATIONS,INDUSTRIES,STOCKS,COLLECTIBLES,PROPERTY,payment,restore,validSave,availableHours,economicState,inventoryQuote,careerLevel,careerPay,careerShiftQuote,cashPlan,milestones,restockPlan,upgradeOptions,acquisitionForecast,businessEconomics,LOGISTICS_ROUTES,cashExposure} from './engine.mjs';
const KEY='business-sim-v1',money=n=>`${n<0?'-':''}$${Math.abs(Math.round(n)).toLocaleString()}`,esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let s,recovered=false;try{let text=localStorage.getItem(KEY),raw=text&&JSON.parse(text);if(text&&!validSave(raw)){localStorage.setItem(KEY+'-recovery',text);recovered=true;}s=text?restore(raw):freshInitial();recovered=recovered||!!localStorage.getItem(KEY+'-recovery');}catch{try{let text=localStorage.getItem(KEY);if(text){localStorage.setItem(KEY+'-recovery',text);recovered=true;}}catch{}s=freshInitial();}let tab='city',chosen=s.businesses[0]?.id,timer;const $=q=>document.querySelector(q);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(s));}catch{toast('Storage is full. Export your save from Save.');}}
const btn=(label,type,args={},cls='')=>{let reason='';if(s?.life&&(type.startsWith('life:')||type==='shift'&&s.life.phase==='career')){try{action(s,type,args);}catch(e){reason=e.message;}}return `<button class="${cls}${reason?' unavailable':''}" data-action="${type}" data-args="${esc(JSON.stringify(args))}" ${reason?`aria-disabled="true" aria-description="${esc(reason)}"`:''}>${label}${reason?`<small class="unavailable-reason">${esc(reason)}</small>`:''}</button>`;};
const stats=items=>`<div class="stats">${items.map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div>`;
function modal(title,body,confirm){let d=$('#modal');delete d.dataset.lifeSheet;delete d.dataset.cashReview;d.setAttribute('aria-labelledby','modal-title');d.innerHTML=`<h2 id="modal-title">${esc(title)}</h2>${body}<div id="confirm"></div><button class="quiet" id="cancel">Back</button>`;d.querySelector('#cancel').onclick=()=>d.close();if(confirm){let b=document.createElement('button');b.className='primary';b.textContent=confirm.label;b.onclick=()=>{d.close();run(confirm.type,confirm.args)};d.querySelector('#confirm').append(b);}d.showModal();}
function reviewSettlement(){if(!s.businesses.length)return false;let q=cashExposure(s);if(!q.shortfall)return false;modal('Review the cash gap',`<p class="cash-warning">Forecast cash after settlement: <strong>${money(q.balance)}</strong></p><p>Gap: ${money(q.shortfall)} after forecast orders, collections, bills and living costs. Side hustles and dividends are excluded; actual cash can differ.</p><p class="small">Still owed afterward: ${money(q.held)} in wages/premises, not charged twice. Continue only if you intend to take this cash risk.</p><button data-nav="report">Inspect cash plan instead</button>`,{label:'Run week anyway',type:'week',args:{}});$('#modal').dataset.cashReview='true';$('#cancel').focus();return true;}
function run(type,args={}){try{let before=stage(s),cashBefore=s.cash;s=action(s,type,args);persist();if(type.startsWith('life:')&&type!=='life:tap'||type==='shift'&&s.life?.phase==='career')toast(s.life.last);if(type==='open'&&s.life)toast('You became an owner. Your company replaces tap-to-earn; your progress carries forward.');if(type==='open'){chosen=s.businesses.at(-1).id;tab='business';window.scrollTo(0,0);}if(type==='work'&&!s.jobProgress)toast('Job complete. '+money(72+(s.businesses.length?25:0)+s.skill*6)+' kept after materials.');if(type==='week'){tab=s.life?.phase==='clicker'?'city':'report';window.scrollTo(0,0);}render();if(type==='life:tap')tapFeedback(s.cash-cashBefore);if($('#modal').open&&$('#modal').dataset.lifeSheet)lifeSheet($('#modal').dataset.lifeSheet,true);if(stage(s)>before&&stage(s)>=2)toast(stage(s)===3?'Your portfolio opens up. The city is now your playing field.':'Your first employee is working. You are becoming an operator.');return true;}catch(e){toast(e.message);return false;}}
function tapFeedback(amount){let b=document.querySelector('[data-action="life:tap"]');if(!b)return;b.classList.add('tap-hit');let float=document.createElement('span');float.className='tap-float';float.setAttribute('aria-hidden','true');float.textContent='+$'+amount.toFixed(2);b.append(float);setTimeout(()=>float.remove(),650);}
function work(){let steps=Math.max(2,5-s.skill);return `<section class="panel cream"><div class="eyebrow" style="color:#647c78">Hands-on work · ${12-s.workThisWeek} jobs left this week</div><h2>Your next customer</h2><p>Complete ${steps} work actions. Earn ${money(90+(s.businesses.length?25:0)+s.skill*6)} revenue, use $18 materials.</p><div class="progress"><span style="width:${s.jobProgress/steps*100}%"></span></div>${btn('Work the job <small>'+s.jobProgress+' / '+steps+' actions · tap or hold</small>','work',{},'primary workbtn')}<div class="actions">${btn('Learn the trade · '+money(60+60*s.skill),'train',{},'quiet')}${btn('Run the week','week',{},'quiet')}</div><p class="small">Skill ${s.skill}/3 · ${s.jobsDone} completed jobs. Hiring replaces routine clicks.</p></section>`;}
function apartment(){return `<section class="panel cream"><div class="eyebrow" style="color:#647c78">Your life, before the empire</div><h2>Build your options</h2><p>A part-time job pays the rent while you learn. Classes improve your skills; a digital side hustle can keep earning after you open a company.</p>${stats([['Job level',careerLevel(s)],['Skill level',s.skill+'/3'],['Shifts left',(CAREERS[s.career]?.slots||3)-s.shifts]])}<div class="actions">${btn('Work a shift · '+money(careerPay(s)),'shift',{},'primary')}${btn('Evening class · $90','class')}</div><details><summary>Choose a job path</summary><div class="pillbar">${Object.entries(CAREERS).map(([id,c])=>btn(c.name+' · '+money(careerPay(s,id))+'/shift','career',{id},s.career===id?'primary':'quiet')).join('')}</div><p class="small">Current path: ${CAREERS[s.career]?.name||'Part-time retail'}; ${CAREERS[s.career]?.hours||6} hours per shift. Coordinator needs skill 1 and job level 1; specialist needs skill 3 and job level 2. Specialist, dispatch and production jobs also need the matching practical course. Each career has its own promotions. Change jobs at the start of a week.</p></details><div class="actions">${btn('Run the week','week',{},'quiet')}</div><p class="small">Living costs $75/week. Side hustles use remaining personal hours at settlement, in the order started. Pause one to prioritize another.</p><details><summary>Side hustles & recurring clients</summary><div class="grid">${Object.entries(HUSTLES).map(([id,k])=>{let h=s.hustles?.find(h=>h.type===id)||(id==='websites'&&s.hustle?{level:s.hustleLevel,active:true}:null);return `<section class="hustle-row"><h3>${k.name}</h3><p class="small">${k.desc} Needs skill ${k.skill}. ${k.hours+(h?Math.floor(h.level/2):0)} hours/week. ${h?money(k.gross+h.level*k.lift)+' sales less '+money(k.cost+h.level*k.expenseLift)+' direct costs, level '+h.level+'/3.':money(k.gross-k.cost)+' starting net/week; setup '+money(k.setup)+'.'}</p><div class="actions">${h?`${btn(h.active?'Pause':'Resume','pauseHustle',{id})}${btn('Upgrade · '+money(k.upgrade+h.level*150),'upgradeHustle',{id})}`:btn('Start '+k.name,'startHustle',{id})}</div>${h?.last?`<p class="small">${h.last.missed?'Last week: no free hours, no sales.':'Last net '+money(h.last.net)+'.'}</p>`:''}</section>`}).join('')}</div></details><details><summary>Practical courses & specialization</summary>${Object.entries(COURSES).map(([id,c])=>`<section class="hustle-row"><h3>${c.name} · ${s.education?.[id]||0}/3</h3><p class="small">${c.desc} ${c.hours} active hours.</p><div class="actions">${btn('Take course · '+money(c.cost),'course',{id})}</div></section>`).join('')}</details></section>`+work();}
function lifeHome(){let l=s.life,goal=l.phase==='clicker'?'Land your first full-time job':'Build toward your first company',hint=l.phase==='clicker'?`${Math.min(6,l.knowledge)}/6 knowledge · ${Math.min(2,l.shifts)}/2 casual shifts`:`Home services: $${startupCost(s,'service')+180+INDUSTRIES.service.wage+INDUSTRIES.service.overhead+75} suggested incl. hire + first-week reserve`,u=LIFE_UPGRADES[l.upgrade];const meter=(name,value,max=100)=>`<div class="life-meter"><div>${name}<b>${Math.round(value)} / ${max}</b></div><progress aria-label="${name}" value="${value}" max="${max}"></progress></div>`;return `<section class="life-room" aria-label="Interactive apartment"><img class="life-art" src="assets/apartment.webp" alt="Your small apartment, with desk, kitchen and bed"><div class="life-hud"><div class="life-title"><b>${l.phase==='clicker'?'Start with what you have':'A steady income. More possibilities.'}</b><span>Day ${l.day} · ${l.hours.toFixed(1)}h today · ${availableHours(s).toFixed(1)}h/week</span></div><div class="life-meters">${meter('Energy',l.energy)}${meter('Knowledge',l.knowledge,l.knowledge<6?6:Math.max(18,l.knowledge))}${meter('Mood',l.mood)}${meter('Nourishment',l.food)}</div><button class="life-goal" ${l.phase==='career'?'data-nav="business"':'data-life-sheet="jobs"'}><b>${goal}</b><small>${hint} →</small></button></div><button class="life-hotspot life-food" data-life-sheet="food"><b>Eat something</b><small>Snack · fast food · meal</small></button><div class="life-tap ${l.phase==='career'?'career-tap':''}">${l.phase==='career'?btn(`<b>Work your shift</b><strong>${money(careerPay(s))}</strong><small>${CAREERS[s.career].hours}h · 28 energy<br>${Math.max(0,CAREERS[s.career].slots-s.shifts)} shifts left / week</small>`,'shift',{},'tap-earn career-earn'):''}${btn(`<b>Tap to earn</b><strong>+$${tapValue(l).toFixed(2)}</strong><small>0.1h · 0.5 energy per tap</small>`,'life:tap',{},l.phase==='career'?'career-side-tap':'tap-earn')}<small>${l.food<15||l.mood-focusPenalty(l,.1)<15?'Low mood or nourishment: half tap earnings':'Small freelance tasks. No real-time wait.'}</small></div><button class="life-hotspot life-rest" data-life-sheet="rest"><b>Rest</b><small>Power nap · nap · sleep</small></button><button class="life-hotspot life-sell" data-life-sheet="sell"><b>Find & sell spare things</b><small>${foundItems(l).length-l.sold.length} ready · ${3-foundItems(l).length} places to look</small></button><p class="life-outcome" role="status">${availableHours(s)<.1?'<b>Weekly work hours used. Rest → Skip to next week.</b><br>':(l.focused||0)>=4?'<b>Work streak: take a break for your mood.</b><br>':''}${esc(l.last)}</p><div class="life-bottom"><button data-life-sheet="upgrade" class="life-upgrade"><b>${u?'Upgrade your hustle':'Opening upgrades complete'}</b><small>${u?esc(u.name)+' · $'+u.cost+' → $'+u.value.toFixed(2)+'/tap':'$1.25 base per tap · bigger goals ahead'} →</small></button><div class="life-tabs"><button data-life-sheet="learn">Learn</button><button data-life-sheet="social">Life</button><button data-life-sheet="jobs">Jobs</button>${l.phase==='career'?'<button data-nav="business">Companies</button>':'<button data-life-sheet="rest">Sleep</button>'}</div></div></section>${l.phase==='career'?`<main class="main"><section class="panel cream"><h2>Your next chapter</h2><p>Your first full-time job opens the weekly simulation. Tapping stays available until you open your first company. Sleep restores your daily 14 hours and energy. Productive work, taps and study share 40 active hours per week. Living costs settle only once per week. Next week skips remaining days and unused time.</p></section>${apartment()}</main>`:''}`;}
function smallOffer(l){let o=offerFor(l),done=l.offerDay===l.day;return `<h3 class="desk-offer-title">Today's small offer</h3><p class="small">One odd job a day. A different offer arrives tomorrow. These do not count as a full-time job.</p>${done?'<p>Completed today. Next offer tomorrow.</p>':btn(`<b>${esc(o.name)} · $${o.pay}</b><small>${o.hours}h · energy -${o.energy} · mood ${o.mood-focusPenalty(l,o.hours)} · food ${o.food} · knowledge +${o.knowledge}</small><small>Needs knowledge ${o.requires} (you have ${l.knowledge}), mood 25 and food 20</small>`,'life:offer',{id:o.id},'life-choice')}`;}
function careerProgress(){let q=careerShiftQuote(s),target=startupCost(s,'service')+180+INDUSTRIES.service.wage+INDUSTRIES.service.overhead+75;return `<section class="career-progress"><p class="career-result" role="status">${esc(s.life.last)}</p><h3>Your next paid shift</h3><p>${money(q.pay)} now · ${q.hours}h · ${q.remaining} shift${q.remaining===1?'':'s'} left this week</p><p class="small">Energy -${q.energy} · mood -${q.mood.toFixed(1)} including your work streak · nourishment -${q.food}. After shift: ${Math.round(q.after.energy)} energy, ${Math.round(q.after.mood)} mood, ${Math.round(q.after.food)} nourishment.</p>${q.after.food<15||q.after.mood<15?'<p class="career-warning">This shift leaves mood or nourishment below 15. Plan food or a break before your next small task, or tap pay will be halved.</p>':''}${btn('<b>Work your shift</b><small>Pay and conditions shown above</small>','shift',{},'life-choice primary')}<div class="career-care"><button data-life-sheet="food">Food options</button><button data-life-sheet="rest">Rest options</button></div><h3>${q.promotion?'Next pay rise':'Top pay in this role'}</h3><progress aria-label="Progress to next career pay rise" value="${q.progress}" max="40"></progress><p>${q.promotion?q.promotion+' more completed '+(q.promotion===1?'shift':'shifts')+' to '+money(q.nextPay)+'/shift. A pay rise applies from the following shift.':'Four pay rises earned. A different career starts its own experience.'}</p><h3>First-company savings</h3><progress aria-label="First-company cash target" value="${Math.max(0,Math.min(s.cash,target))}" max="${target}"></progress><p>${money(s.cash)} of ${money(target)} suggested for home services, first recruit and first-week reserve. ${money(Math.max(0,target-s.cash))} to go.</p><p class="small">This is guidance, not a charge or a locked balance. Food purchases and your next living-cost settlement can change available cash. Tapping stays until you open a company.</p><button data-nav="business" class="life-choice">Review company openings →</button></section>`;}
function lifeSheet(kind,refresh=false){let l=s.life;if(!l)return;let title='',body='';const activity=id=>{let a=LIFE_ACTIVITIES[id],mood=a.mood-(a.knowledge?focusPenalty(l,a.hours):0),effects=[a.cost?'$'+a.cost:'Free',a.hours+'h',a.energy?'energy '+(a.energy>0?'+':'')+a.energy:'',mood?'mood '+(mood>0?'+':'')+mood:'',a.food?'food '+(a.food>0?'+':'')+a.food:'',a.knowledge?'knowledge +'+a.knowledge:''].filter(Boolean).join(' · ');return btn(`<b>${a.name}</b><small>${effects}</small>`,'life:activity',{id},'life-choice');};switch(kind){
 case 'learn':title='Your desk';body='<p>Every 6 knowledge earns a foundation skill (max 3). After 4 focused hours, study costs 2 extra mood/hour. A proper break resets the streak.</p>'+['book','course','seminar'].map(activity).join('')+smallOffer(l);break;
 case 'food':title='Eat something';body=['snack','fastfood','meal'].map(activity).join('')+btn('<b>Pantry portion</b><small>Free · 0.25h · food +20 · once per day</small>','life:pantry',{},'life-choice')+'<p class="small">Below 15 nourishment, tap earnings are halved. Sleep uses 15 nourishment. Free pantry food prevents a cash lock.</p>';break;
 case 'rest':title='Rest and recover';body=['powernap','nap'].map(activity).join('')+btn('<b>Real sleep · next day</b><small>Energy → 100 · mood +12 · food -15 · 14h new daily time</small>','life:sleep',{},'life-choice primary')+`<p>Day ${l.day}. Sleep moves one personal day. Productive work, tapping and learning share 40 active hours/week; food, rest and social time use only daily hours. Every seventh night settles the week, including $75 living costs. No real-time wait. Food purchases are extra.</p>`+btn('<b>Skip to next week</b><small>Settle $75 living costs now · remaining days/time skipped · overnight food/mood changes apply</small>','week',{},'life-choice');break;
 case 'social':title='Make room for life';body='<p>Work and study wear on mood. Walks and friends clear the work streak. Below 15 mood, tap earnings are halved. Walks and friends restore it.</p>'+['walk','friend'].map(activity).join('');break;
 case 'sell':title='Around your room';body='<p>Explore two places, then list what you find. Fictional Facebook listings, not a connection to your real account. Each sale pays once and uses 0.5h + 4 energy.</p>'+Object.entries(HOUSEHOLD).filter(([id])=>foundItems(l).includes(id)).map(([id,a])=>l.sold.includes(id)?`<p>${a.name} · sold</p>`:btn(`<b>${a.name}</b><small>Sell for $${a.cash} · one-off</small>`,'life:sell',{id},'life-choice')).join('')+Object.entries(SEARCH_SPOTS).filter(([,spot])=>!foundItems(l).includes(spot.item)).map(([id,spot])=>btn(`<b>${spot.name}</b><small>${spot.hours}h · ${spot.energy} energy · find something to list</small>`,'life:search',{id},'life-choice')).join('');break;
 case 'upgrade':{title='Upgrade your hustle';let u=LIFE_UPGRADES[l.upgrade];body=u?btn(`<b>${u.name} · $${u.cost}</b><small>1h · 5 energy · base tap earnings → $${u.value.toFixed(2)}</small>`,'life:upgrade',{},'life-choice primary'):'<p>All three opening upgrades are complete. Build skills and employment to reach larger opportunities.</p>';break;}
 case 'jobs':title='From odd jobs to a career';body=`<p>${l.phase==='career'?esc(CAREERS[s.career].name)+' secured. Your weekly career and company options are open.':`Full-time role needs 6 knowledge (${l.knowledge} now) and 2 casual shifts (${l.shifts} completed). Casual work does not end the clicker phase.`}</p>`+(l.phase==='clicker'?btn('<b>Part-time retail</b><small>$55/shift · 6h · 28 energy · mood -9 · food -14</small>','life:job',{id:'retail'},'life-choice')+btn('<b>Casual warehouse</b><small>$65/shift · same time and condition costs</small>','life:job',{id:'warehouse'},'life-choice')+(l.employment!=='unemployed'?btn('<b>Work a casual shift</b><small>Current role: '+esc(l.employment)+' · max 3 shifts/week</small>','life:casualShift',{},'life-choice primary'):'')+btn('<b>Apply for full-time coordinator</b><small>Needs 6 knowledge + 2 completed casual shifts</small>','life:job',{id:'office'},'life-choice'):careerProgress());break;
 default:return;
 }body=`<div class="life-sheet-status">$${s.cash.toFixed(2)} · ${l.hours.toFixed(1)}h today · ${availableHours(s).toFixed(1)}h/week · Work streak ${(l.focused||0).toFixed(1)}h · Energy ${Math.round(l.energy)} · Mood ${Math.round(l.mood)} · Food ${Math.round(l.food)}</div>`+body+`<p class="life-sheet-result" role="status">${esc(l.last)}</p>`;let d=$('#modal'),scroll=refresh?d.scrollTop:0;if(refresh){let active=document.activeElement,actionKey=active?.dataset?.action,argsKey=active?.dataset?.args;d.innerHTML=`<h2 id="modal-title">${title}</h2>${body}<button class="quiet" id="cancel">Back to room</button>`;d.querySelector('#cancel').onclick=()=>d.close();if(actionKey)[...d.querySelectorAll('[data-action]')].find(x=>x.dataset.action===actionKey&&x.dataset.args===argsKey)?.focus({preventScroll:true});}else modal(title,body);d.dataset.lifeSheet=kind;d.scrollTop=scroll;}

function ownerHUD(){let b=s.businesses.find(x=>x.id===chosen)||s.businesses[0];if(!b)return '';let f=forecast(s,b),plan=cashPlan(s),recruit=180+40*b.staff;return `<div class="owner-hud"><div class="owner-title"><span>YOUR COMPANY · WEEK ${s.week}</span><h1>${esc(b.name)}</h1></div><section class="owner-scoreboard" aria-label="Company operating forecast"><div><span>Sales forecast</span><b>${money(f.revenue)}</b></div><div><span>Operating profit</span><b>${money(f.profit)}</b></div><div class="owner-capacity"><span>Demand you can serve <b>${f.units} / ${f.demand} ${esc(f.unit)}</b></span><progress aria-label="Demand served" value="${f.units}" max="${Math.max(1,f.demand)}"></progress><small>${b.staff?esc(f.bottleneck)+(f.stockShortfall?' · stock shortage '+f.stockShortfall:''):'No employees yet. Hire capacity before running the week.'}</small></div></section><button class="owner-manage" data-nav="business"><b>${b.manager?'Your manager runs the routine':'Build the team. Build the system.'}</b><small>${b.staff} employee${b.staff===1?'':'s'} · ${b.manager?'manager hired':'you lead operations'} · inspect costs and controls →</small></button></div><div class="owner-world-actions">${b.staff<2&&s.cash<recruit?`<button class="owner-world-button" data-nav="business"><b>Build hiring cash</b><small>Next recruit ${money(recruit)} · available ${money(s.cash)} · inspect options →</small></button>`:b.staff<2?btn(`<b>Hire ${b.staff?'another employee':'your first employee'}</b><small>${money(recruit)} recruiting now · +${money(INDUSTRIES[b.type].wage)}/week wages</small>`,'hire',{id:b.id},'owner-world-button'):!b.manager?btn('<b>Hire a manager</b><small>$600 onboarding · +$110/week · needs 2 employees</small>','manager',{id:b.id},'owner-world-button'): '<button class="owner-world-button" data-nav="deals"><b>Find your next opportunity</b><small>A second industry, property or a founder →</small></button>'}<button class="owner-world-button" data-nav="business"><b>Inspect the business</b><small>People · pricing · stock · tools →</small></button></div><div class="owner-week"><p>${s.cash<plan.reserve?'Cash warning: '+money(plan.reserve)+' forecast gap; you have '+money(s.cash)+'.':'Next week: '+money(plan.net)+' cash forecast.'} Living costs included. Not guaranteed.</p>${btn('<b>Run the next week</b><small>Operations + bills settle together →</small>','week',{},'owner-settle')}</div>`;}
function home(){if(s.life&&s.life.phase!=='owner')return lifeHome();let plan=cashPlan(s);let city=stage(s)>=3,f=s.businesses[0]&&forecast(s,s.businesses[0]);return `<div class="scene ${city?'city':''}"><img src="assets/${city?'city':s.businesses.length?'workshop':'apartment'}.webp" alt="${city?'Your illustrated isometric neighborhood':s.businesses.length?'Your first workshop on the neighborhood street':'Your illustrated apartment workspace'}">${s.life?.phase==='owner'&&!city?ownerHUD():''}${city?'<button class="pin pin-a" data-nav="business">Your companies</button><button class="pin pin-b" data-nav="property">Property portfolio</button><button class="pin pin-c" data-nav="deals">Opportunities</button>':''}<div class="scene-copy"><div class="eyebrow">${city?'Your city · your choices':s.businesses.length?'From one pair of hands':'Your apartment · a new start'}</div><h1>${city?'The bigger picture':s.businesses.length?'Build something that lasts':'Every empire starts somewhere'}</h1><p>${city?'Businesses, buildings and capital. The same city, a different kind of game.':'Work the jobs. Learn the trade. Hire a team. Your world opens up as you grow.'}</p></div><button class="scene-action" data-focus-controls>${city?'Explore expansion':s.businesses.length?'Manage your first business':'Plan your first business'} <span aria-hidden="true">›</span></button></div><main class="main" id="home-controls">${recovered?'<section class="panel"><h2>A save needs repair</h2><p>Your stored save could not be safely loaded. Its original data was kept on this device before starting this preview.</p><button id="recover-save">Download original data</button><p class="small">Keep that file before importing a working save. This does not erase the saved original.</p></section>':''}<details class="panel journey"><summary>Your next steps · ${milestones(s).filter(m=>m.done).length}/${milestones(s).length}</summary><ol>${milestones(s).map(m=>`<li class="${m.done?'done':''}">${m.done?'✓ ':''}${m.name}</li>`).join('')}</ol><p class="small">No resets or paid shortcuts. The same life, companies and investments carry forward.</p></details><div class="notice">${nextGoal(s)}<div class="small">${economicState(s).name} · through week ${s.economy?.until-1||3}.</div><div class="small">${availableHours(s)} of 40 active hours remain this week. Job shifts, classes and hands-on orders share your time; employees work separately.</div></div>${stage(s)<2?(s.businesses.length?work():apartment()):`<section class="panel cream"><div class="eyebrow" style="color:#647c78">Your next decision</div><h2>${f?.missed?'Demand is ahead of capacity':'Let the system do the work'}</h2><p>${f?.missed?f.missed+' requests exceed capacity. Hire, buy equipment or test your prices. More ads alone will not fix it.':'Inspect your companies, choose what to fund and run the next week.'}</p><div class="actions"><button data-nav="business" class="primary">Manage the company</button>${btn('Run the week','week')}</div></section>`}<section class="panel"><h3>Before the next week</h3>${stats([['Bills forecast',money(plan.outflow)],['Collections + rents',money(plan.collections+plan.rent)],['Operating cash change',money(plan.net)]])}<p class="small">Managed stock orders ${money(plan.restock)}, wages ${money(plan.payroll)}, premises ${money(plan.premises)}, other operations ${money(plan.variable+plan.investors)}, property costs ${money(plan.mortgage+plan.maintenance)}, loans ${money(plan.loans)}, living/carrying ${money(75+plan.carrying)}. Excludes manual purchases, side hustles and dividends. Demand, production and tenant changes can move actual results.</p>${plan.reserve>s.cash?`<div class="notice">Available cash is below the projected ${money(plan.reserve)} gap. Reduce commitments, work, or sell an asset before advancing.</div>`:''}</section><div class="grid"><section class="panel"><h3>Your position</h3>${stats([['Cash',money(s.cash)],['Net worth',money(worth(s))],['Companies',s.businesses.length]])}<p class="small">Company values and founder stakes are estimates, not spendable cash.</p><div class="phasepath">${[0,1,2,3].map(x=>`<span class="${stage(s)>=x?'done':''}"></span>`).join('')}</div><p class="small">Hands-on → founder → operator → investor</p></section><section class="panel"><h3>What is happening</h3><p>${esc(s.events[0]?.title||'Your first customer is waiting')}</p><p class="small">${esc(s.events[0]?.body||'Opening cash: $110. Build your start through customer work.')}</p><div class="actions"><button data-nav="report">Open the ledger</button></div></section></div>${stage(s)>=2?`<details class="panel life-controls"><summary>Your job, skills & side hustle</summary>${apartment()}</details>`:''}</main>`;}
function cafeStyleOptions(b){if(b.type!=='cafe')return '';return `<section class="panel cafe-style-options"><h3>Choose your service style</h3><p class="small">Serve more visits at a lower ticket, or fewer at a higher ticket. No setup charge or stock conversion. Ingredient cost basis stays with the packs you bought. Price setting multiplies this ticket.</p>${Object.entries(CAFE_STYLES).map(([id,k])=>{let x=structuredClone(b);x.cafeStyle=id;let f=forecast(s,x);return `<div class="forecast"><strong>${esc(k.name)} ${id===(b.cafeStyle||'standard')?'· active':''}</strong><p class="small">${k.desc}</p><p class="small">${'$'+f.price.toFixed(2)}/visit · capacity ${f.capacity} · demand ${f.demand} · ${f.units} visits served · profit ${money(f.profit)}/week at current stock.</p>${id===(b.cafeStyle||'standard')?'':btn('Use '+k.name,'cafeStyle',{id:b.id,style:id})}</div>`;}).join('')}<p class="small">Snapshot, not a promise. Missing stock can hide a style's potential. More capacity does not create demand; unsold ingredients still spoil.</p></section>`;}
function logisticsRoutes(b){if(b.type!=='logistics')return '';let active=b.route||'accounts';return `<section class="panel route-options"><div class="eyebrow">Dispatch desk · next settlement</div><h3>Choose your dispatch plan</h3><p class="small">A free, reversible choice for new deliveries. Existing invoices keep their original due dates.</p><div class="route-grid">${Object.entries(LOGISTICS_ROUTES).map(([id,k])=>{let x={...b,route:id},f=forecast(s,x),q=cashPlan({...s,businesses:s.businesses.map(y=>y.id===b.id?x:y)}).companies.find(y=>y.id===b.id);return `<article class="route-card ${id===active?'selected':''}"><div class="route-heading"><h4>${k.name}</h4><span>${id===active?'Active':k.lag?'2-week terms':'Paid now'}</span></div><p class="route-summary">${f.units} deliveries · $${f.price.toFixed(2)} ticket<br>New sales paid ${k.lag?'week '+(s.week+k.lag):'this settlement'}</p><dl><div><dt>Operating profit</dt><dd>${money(f.profit)}</dd></div><div><dt>Company cash change</dt><dd class="${q.net<0?'negative':'positive'}">${money(q.net)}</dd></div></dl><details class="route-terms"><summary>Capacity & fuel</summary><p class="small">${k.desc} Capacity ${f.capacity} stops. Fuel per delivered stop $${(f.units?f.inputs/f.units:INDUSTRIES.logistics.input*economicState(s,'logistics').input*Math.max(.8,1-b.tools*.04)*k.input).toFixed(2)}.</p></details>${id===active?'<p class="route-active">Current dispatch plan</p>':btn('Switch to '+k.name,'route',{id:b.id,route:id})}</article>`;}).join('')}</div><p class="small">Snapshot with current staff, fuel prices and demand. Cash change includes existing invoice collections and due bills, not personal living costs. Higher tickets do not guarantee higher profit. No setup charge.</p></section>`;}
function companyCashTiming(b){let q=cashPlan(s).companies.find(x=>x.id===b.id);if(!q)return '';let invoices=(b.receivables||[]).reduce((m,r)=>{let due=Math.max(s.week,r.due);m[due]=(m[due]||0)+r.amount;return m;},{});return `<section class="panel company-cash-timing"><div class="eyebrow">Settlement week ${s.week} forecast</div><h3>Profit isn't spendable cash</h3><div class="rows">${[['Sales earned',q.sales],['Accounting profit',q.profit],['Customer cash collected',q.collections],['Manager stock order',-q.stockCost],['Wages paid now',-q.payroll],['Premises paid now',-q.premises],['Other operating cash',-q.variable],['Investor profit share',-q.investors],['Company cash change',q.net]].map(([name,value])=>`<div class="split"><span>${name}</span><strong class="num ${value<0?'negative':'positive'}">${money(value)}</strong></div>`).join('')}</div><p class="small">${businessEconomics(b).lag?money(q.newInvoices)+' of projected new sales waits until settlement week '+q.invoiceDue+'. '+(q.newInvoices?'':'No saleable output is forecast yet.'):'Sales pay at completion; no new delayed invoices.'} ${q.stockCost?money(q.stockCost)+' stock paid before selling.':'Manual stock already bought is not paid twice here.'}</p><h3>Bills that remain after this settlement</h3><p class="small">Accrued wages ${money(q.wagesHeld)} · premises ${money(q.premisesHeld)}. ${q.payrollIn?'Next payroll in '+q.payrollIn+' more settlement'+(q.payrollIn===1?'':'s')+'.':'Payroll is due now.'} ${q.premisesIn?'Next premises bill in '+q.premisesIn+' more settlement'+(q.premisesIn===1?'':'s')+'.':'Premises bill is due now.'} Future wages/rent keep adding until paid.</p><details><summary>Existing invoice schedule · ${money((b.receivables||[]).reduce((n,r)=>n+r.amount,0))}</summary>${Object.entries(invoices).sort((a,b)=>Number(a[0])-Number(b[0])).map(([week,value])=>`<div class="split"><span>Settlement week ${week}</span><strong>${money(value)}</strong></div>`).join('')||'<p class="small">No existing unpaid customer invoices.</p>'}</details><p class="small">Forecast for this firm, not the whole portfolio. Excludes personal $75 living costs, property, loans and side hustles. The Books cash plan includes them. Demand, production and manager order budgets can change results. Taxes are not modeled.</p><button data-nav="report">Whole-portfolio cash plan →</button></section>`;}
function business(){let b=s.businesses.find(x=>x.id===chosen)||s.businesses[0];chosen=b?.id;let out='<main class="main"><div class="section-head"><div><div class="eyebrow">Operations</div><h1>Your companies</h1><p class="small">Demand, conversion, capacity and costs.</p></div><button data-nav="deals">+ New</button></div>';if(!b)return out+`<section class="panel"><h2>From worker to owner</h2><p>Fit out a service company for $450. Keep cash for recruiting and weekly bills.</p><div class="actions">${btn('Start home services · $450','reviewOpen',{industry:'service'},'primary')}<button data-nav="city">Earn the start</button></div></section></main>`;let k=INDUSTRIES[b.type],f=forecast(s,b),o=OPERATIONS[b.type],eco=businessEconomics(b);return out+`<div class="pillbar">${s.businesses.map(x=>`<button data-business="${x.id}" class="${x.id===chosen?'active':''}">${esc(x.name)}</button>`).join('')}</div><section class="panel cream"><div class="eyebrow" style="color:#647c78">Location ${b.location} · ${b.manager?'Manager-led':'Owner-led'}</div><h2>${esc(b.name)}</h2>${stats([['Weekly sales',money(f.revenue)],['Weekly profit',money(f.profit)],['Indicative value',money(valuation(s,b))]])}<p class="small">Forecast, not guaranteed income. Sale value depends on dependable profit and owner independence.</p></section>${logisticsRoutes(b)}<div class="grid"><section class="panel"><h3>The demand engine</h3><p class="small">${eco.policy}. ${BILLING[b.type].label}; ${(b.size||1)>1?'fortnightly':'weekly'} payroll. Accrued bills ${money((b.payrollDue||0)+(b.premisesDue||0))}. ${b.last?'Last collected '+money(b.last.collected||0)+'; cash change '+money(b.last.net||0)+'.':''}</p>${stats([['Leads',f.leads],['Conversion',Math.round(f.conversion*100)+'%'],['Demand',f.demand]])}<div class="controls"><label>Price per sale<select data-setting="price" data-id="${b.id}">${[.8,1,1.2,1.4].map(x=>`<option value="${x}" ${b.price===x?'selected':''}>${b.type==='cafe'?'$'+(k.price*CAFE_STYLES[b.cafeStyle||'standard'].price*x).toFixed(2):(b.type==='logistics'?'$'+(k.price*LOGISTICS_ROUTES[b.route||'accounts'].price*x).toFixed(2):money((b.type==='manufacturing'?PRODUCTS[b.product||'components'].price:k.price)*x))} · ${Math.round(x*100)}%</option>`).join('')}</select></label><label>Advertising<select data-setting="marketing" data-id="${b.id}">${[0,1,2,3].map(x=>`<option value="${x}" ${b.marketing===x?'selected':''}>${money(x*85)} / week</option>`).join('')}</select></label></div><div class="actions">${btn((b.outreach?'Stop ':'Start ')+o.reach+' · '+money(o.reachCost)+'/week','outreach',{id:b.id})}${btn((b.knockers?'Stop ':'Start ')+o.field+' · '+money(o.fieldCost)+'/week','knocker',{id:b.id})}${b.type==='manufacturing'?btn('Input contracts · '+(b.supply||0)+'/2','supply',{id:b.id}):''}</div><div class="forecast"><strong>${esc(f.rival.name||'Local rival')}</strong><p class="small">${esc(f.rival.move||'Holding prices')} · ${Math.round(f.rival.price*100)}% price level · ${Math.round(f.rival.quality*100)}% quality. Your offer wins more demand with a better price/quality balance, but margins still matter.</p></div>${f.stockShortfall?`<div class="notice">${f.stockShortfall} ${o.unit} could fit capacity and demand but lack finished stock. ${b.type==='manufacturing'?'Buy packs and schedule production. Recipe lead time may delay finished goods.':'Restock before buying more ads or hiring.'}</div>`:''}<p class="small">Cost / extra inquiry: ${b.marketing?money(f.acquisitionCost):'No paid campaign'}. Repeat strength: ${b.loyalty.toFixed(1)}.</p></section><section class="panel">${eco.stock?`<section class="panel"><h3>${b.type==='manufacturing'?'Production inputs & finished batches':'Stock ready to sell'}</h3>${b.type==='manufacturing'?`<p><strong>${PRODUCTS[b.product||'components'].name}</strong></p><p class="small">${PRODUCTS[b.product||'components'].desc} Work-in-progress ${(b.productionQueue||[]).reduce((n,q)=>n+q.count,0)} units. Recipe changes require an empty finished-goods line.</p><div class="actions">${Object.entries(PRODUCTS).map(([id,p])=>btn(p.name,'product',{id:b.id,product:id},(b.product||'components')===id?'primary':'')).join('')}</div>`:''}<p>${b.type==='manufacturing'?'Inputs '+(b.rawStock||0)+' packs · finished ': 'Inventory '}${b.inventory||0} ${o.unit}. Purchased for ${money(f.inputPrice)} each on new purchases, then sold over time. Available demand ${f.potential}; actual sales ${f.units}.</p><div class="actions">${btn((b.type==='manufacturing'?'Buy 10 input packs · ':'Buy 10 · ')+money(inventoryQuote(s,b,10)),'buyStock',{id:b.id,count:10})}${btn((b.type==='manufacturing'?'Buy 50 input packs · ':'Buy 50 · ')+money(inventoryQuote(s,b,50)),'buyStock',{id:b.id,count:50})}${b.type==='manufacturing'?btn('Produce up to 10 batches','produce',{id:b.id},'primary')+(b.manager?btn(b.autoProduction?'Stop delegated production':'Delegate production to manager','autoProduction',{id:b.id}):''):''}</div>${b.manager?`<div class="forecast"><h3>Let your manager restock</h3><p class="small">Orders enough for projected capacity/demand, up to your weekly budget. Never purchases below $500 cash before bills. This reserve may not cover all wages, rent or debt. No fixed purchase when inventory is already sufficient.</p><div class="controls"><label>Stock purchase limit per week<select data-setting="restockBudget" data-id="${b.id}">${[250,1000,3000].map(n=>`<option value="${n}" ${(b.restockBudget||1000)===n?'selected':''}>${money(n)}</option>`).join('')}</select></label></div><div class="actions">${btn(b.autoRestock?'Stop automatic restocking':'Review automatic restocking','reviewRestock',{id:b.id})}</div><p class="small">${b.autoRestock?'Next order now: '+restockPlan(s,b).count+' units, '+money(restockPlan(s,b).cost)+'. May change with cash and other firms.':'Restocking is off. Manual purchasing still works.'}</p></div>`:''}<p class="small">${b.type==='manufacturing'?'Buy inputs, schedule production, wait for any recipe lead time, then sell finished stock. Receivables collect two weeks after sale.':b.type==='cafe'?'20% of unsold ingredients spoil each week. Buy for demand, not shelf size.':'Unsold stock carries forward; it is not automatically converted to cash.'}</p></section>`:''}<h3>Capacity & quality</h3><p class="small">Equipment condition ${Math.round(f.condition)}%. Below 60% it reduces throughput.</p><div class="actions">${btn('Maintain · '+money(Math.round(k.tool*.18*(1+b.tools*.4))),'maintenance',{id:b.id})}</div><p class="small">${esc(f.bottleneck)} · measured in ${o.unit}/week</p>${stats([['Employees',b.staff],['Capacity',f.capacity],['Unfilled demand',f.missed]])}<p class="small">${o.upgrade} ${b.tools}/3 · training ${b.training}/3. ${b.staff?'':'No crew yet: only your manual jobs earn money.'}</p><div class="actions">${btn('Hire · '+money(180+40*b.staff),'hire',{id:b.id},'primary')}${btn(o.upgrade+' · '+money(k.tool*(1+b.tools*.5)),'tool',{id:b.id})}${btn('Team training · $150','staffTrain',{id:b.id})}</div><details class="upgrade-options"><summary>Compare the next upgrade</summary><p class="small">Snapshot at current demand, prices, stock and condition. Not a promise, cash forecast or payback estimate. Missing stock and later recipe completion can change sales. Employee wages are included in weekly profit change; purchase costs are paid separately.</p>${upgradeOptions(s,b).map(x=>`<div class="forecast"><strong>${x.name} · ${money(x.cost)} now</strong><p class="small">Capacity ${x.capacity} (${x.capacityChange>=0?'+':''}${x.capacityChange}), sales ${x.salesChange>=0?'+':''}${x.salesChange}, weekly operating profit ${x.profitChange>=0?'+':''}${money(x.profitChange)}. Afterward: ${esc(x.bottleneck)}.</p>${x.profitChange<=0?'<p class="small">No immediate modeled profit gain. Consider the current bottleneck before buying.</p>':''}</div>`).join('')}</details></section></div><section class="panel"><h3>How operating profit is calculated</h3><div class="rows">${[['Sales',f.revenue],['Materials & stock',-f.inputs],['Wages',-f.wages],['Premises & overhead',-f.overhead],['Advertising',-f.adCost],['Manager',b.manager?-110:0],['Input contract',-f.extra],['Operating profit',f.profit]].map(([n,v])=>`<div class="split"><span>${n}</span><strong class="num ${v<0?'negative':'positive'}">${money(v)}</strong></div>`).join('')}</div><p class="small">Inventory purchases use cash before sale; sold stock is an expense in profit. Outstanding invoices: ${money((b.receivables||[]).reduce((a,x)=>a+x.amount,0))}. Taxes are not modeled yet.</p></section>${companyCashTiming(b)}${cafeStyleOptions(b)}<section class="panel"><h3>Build beyond yourself</h3><p class="small">Footprint ${b.size||1}/2 · larger premises add physical capacity, not free worker hours. Fixed overhead grows.</p><div class="actions">${btn('Larger footprint · '+money(k.cost*.7),'size',{id:b.id})}</div><p class="small">${b.investor?'Outside investor owns 20% and receives 20% of positive profit and sale proceeds.':'You own 100%. An outside investor can fund growth in exchange for permanent equity.'}</p><div class="actions">${!b.investor?btn('Review outside investment','reviewOutside',{id:b.id}):''}${btn('Review growth loan','reviewLoan',{id:b.id})}</div><p>${b.manager?'Your manager runs the routine. Open a branch or review an exit.':'Two employees unlock a manager: $600 onboarding, then $110/week. A managed company commands a better offer.'}</p><div class="actions">${b.manager?btn('Open branch · '+money(k.cost*1.3+b.tools*k.tool*.6),'reviewBranch',{id:b.id}):btn('Hire manager · $600','manager',{id:b.id})}${btn('Review buyer offer','reviewSale',{id:b.id})}${btn('Release employee · $100','reviewFire',{id:b.id},'quiet')}</div></section></main>`;}
function property(){return `<main class="main"><div class="section-head"><div><div class="eyebrow">Buildings & tenants</div><h1>Property</h1></div></div><div class="grid">${Object.entries(PROPERTIES).map(([id,k])=>`<section class="panel cream"><div class="eyebrow">${k.kind}</div><h2>${k.name}</h2><p>${k.tenant}. A mortgage pays down over time, but vacancy and repairs do not stop debt payments.</p>${stats([['Purchase',money(k.price)],['Down payment',money(k.deposit)],['Mortgage / week',money(payment(k.loan,k.rate,k.term))]])}<p class="small">${money(k.loan)} financed · ${(k.rate*100).toFixed(1)}% fixed annual rate · ${k.term} weekly payments. Rent at target occupancy ${money(k.rent*k.occupancy)}/week; maintenance ${money(k.maintenance)}. Selling costs 6%. Lease review after ${k.lease} weeks.</p><div class="actions">${s.properties.some(p=>(p.kind||'apartments')===id)?'<span>In your portfolio</span>':btn('Review purchase','reviewProperty',{kind:id},'primary')}</div></section>`).join('')}</div>${s.properties.map(p=>{let k=PROPERTIES[p.kind||'apartments'];return `<section class="panel"><div class="eyebrow">Owned · ${Math.round(p.occupied*100)}% occupancy · Condition ${Math.round(p.condition??100)}%</div><h2>${esc(p.name)}</h2>${stats([['Equity',money(p.value-p.debt)],['Debt',money(p.debt)],['Renovations',p.renovation+'/2']])}<p class="small">${p.last?'Last net rent '+money(p.last.net)+', after maintenance and mortgage. Principal paid '+money(p.last.principal)+'.':'Rent settles at the end of the week.'} ${esc(p.tenant||k.tenant)}. Low condition can reduce occupancy. Lease review week ${p.leaseEnds||'unrecorded'}.</p><div class="actions">${btn('Renovate · '+money(k.renovation),'renovate',{id:p.id})}${btn('Repair · '+money(k.repairCost),'repairProperty',{id:p.id})}${p.occupied<k.occupancy?btn('Find tenant · '+money(k.rent*.5),'leaseProperty',{id:p.id}):''}${btn('Review sale','reviewPropertySale',{id:p.id})}</div></section>`}).join('')}<p class="footer-note">Each listed property is unique. This slice models lease reviews, vacancy, condition and debt, not tenant-by-tenant simulation or owner-occupied business premises.</p></main>`;}
let dealTab='companies';
function deals(){let p=s.startups.find(x=>x.active&&!x.funded);return `<main class="main"><div class="section-head"><div><div class="eyebrow">Capital & opportunity</div><h1>Deals & markets</h1></div></div><div class="pillbar">${[['companies','Companies'],['founders','Founders'],['markets','Markets'],['collectibles','Collectibles']].map(([id,label])=>`<button data-dealtab="${id}" class="${dealTab===id?'active':''}">${label}</button>`).join('')}</div>${dealTab==='companies'?`<div class="grid">${Object.entries(INDUSTRIES).map(([id,k])=>`<section class="panel"><div class="eyebrow">Start from scratch</div><h2>${k.name}</h2><p>${k.desc}</p><p class="small">${ECONOMICS[id].policy}. ${BILLING[id].label}; payroll weekly for a small site, fortnightly for a larger site. ${ECONOMICS[id].stock?'Inventory capital is separate. ':''}Fit-out ${money(startupCost(s,id))}, weekly overhead ${money(k.overhead)} before wages and materials. Hire capacity separately.</p><div class="actions">${btn('Start · '+money(startupCost(s,id)),'reviewOpen',{industry:id},'primary')}</div></section>`).join('')}<section class="panel cream"><div class="eyebrow" style="color:#647c78">Acquisition</div><h2>Corner & Co.</h2><p>Two staff, returning customers and no manager. The owner is leaving. Buy, improve and sell an operating business.</p><div class="actions">${btn('Open the books','reviewAcquire',{},'primary')}</div></section></div>`:dealTab==='founders'?founder(p):dealTab==='markets'?`<div class="notice">Fictional assets, simulated prices, no real money. Orders settle at the displayed price, with a 1% fee each way.</div><div class="grid">${s.market.map(m=>{let k=STOCKS.find(x=>x.id===m.id),min=Math.min(...m.history)*.98,max=Math.max(...m.history)*1.02;return `<section class="panel"><div class="eyebrow">${k.sector}</div><h2>${k.name}</h2>${stats([['Price',money(m.price)],['Shares owned',s.stocks[m.id]||0],['Holding value',money(m.price*(s.stocks[m.id]||0))]])}<svg class="chart" viewBox="0 0 300 65" role="img" aria-label="Simulated weekly price history"><polyline fill="none" stroke="#edbc65" stroke-width="2" points="${m.history.map((v,i)=>`${i/Math.max(1,m.history.length-1)*300},${60-(v-min)/(max-min)*55}`).join(' ')}"/></svg><p class="small">${m.history.length} weekly observations · ${(k.yield*100).toFixed(2)}% dividend / week.</p><div class="actions">${btn('Buy 10 · '+money(m.price*10*1.01),'stock',{id:m.id,count:10})}${btn('Sell 10','stock',{id:m.id,count:10,sell:true})}</div></section>`}).join('')}</div><p class="footer-note">Seeded market-cycle model, not real feeds or a full earnings simulation.</p>`:`<div class="grid">${COLLECTIBLES.map(c=>`<section class="panel cream"><div class="eyebrow" style="color:#647c78">Authenticated provenance</div><h2>${c.name}</h2><p>Storage ${money(c.storage)}/week, sale spread ${c.spread*100}%, buyer available after two weeks. Paper value can change while cash is tied up.</p><div class="actions">${btn('Acquire · '+money(c.price),'collect',{id:c.id},'primary')}</div></section>`).join('')}${s.collectibles.map(c=>`<section class="panel"><h3>${esc(c.name)}</h3><p>Estimated value ${money(c.value)}. Net sale ${money(c.value*(1-c.spread))}.</p><p class="small">${c.age} weeks held.</p><div class="actions">${btn('Sell through dealer','sellCollect',{id:c.id})}</div></section>`).join('')}</div>`}</main>`;}
let selectedFounder='loop';
function founder(){let fid=selectedFounder,k=FOUNDERS[fid],p=s.startups.find(x=>x.active&&(x.founder||'loop')===fid);return `<div class="pillbar">${Object.entries(FOUNDERS).map(([id,f])=>`<button data-founder="${id}" class="${id===fid?'active':''}">${f.name}</button>`).join('')}</div><section class="panel cream"><div class="eyebrow">Founder pitch · ${k.sector}</div><h2>${k.name}</h2><p>${esc(k.pitch)}</p><p class="small">The ask: ${money(k.ask)} for ${k.equity*100}% at ${money(k.ask/k.equity)} post-money valuation. Fictional founder, authored answers, simulated outcomes.</p><div class="actions">${Object.entries(k.questions).map(([id,[q]])=>btn(q,'question',{id,founder:fid})).join('')}</div>${(s.founderQuestions?.[fid]||[]).map(q=>`<div class="forecast"><strong>${k.questions[q][0]}</strong><p>${k.questions[q][1]}</p></div>`).join('')}${p?.diligence?`<div class="forecast"><h3>Books review: ${esc(DILIGENCE[fid].finding)}</h3><p>${esc(DILIGENCE[fid].confirmed)}</p><p>${esc(DILIGENCE[fid].risk)}</p><p class="small">${esc(DILIGENCE[fid].terms)}</p></div>`:''}<div class="forecast"><p>Illiquid capital. Failure can lose the investment. Diligence and help reduce modeled risk, not remove it.</p><div class="actions">${(s.startups.some(x=>x.funded&&(x.founder||'loop')===fid)||(s.closedInvestments||[]).some(x=>x.founder===fid))?'<span>Investment outcome recorded below</span>':`${p?.diligence?btn('Negotiate '+k.negotiate*100+'% for '+money(k.ask),'reviewStartup',{offer:'negotiate',founder:fid}):btn('Verify books · '+money(k.diligence),'diligence',{founder:fid})}${btn('Accept '+k.equity*100+'% for '+money(k.ask),'reviewStartup',{offer:'accept',founder:fid},'primary')}`}</div></div></section>${s.startups.filter(x=>x.funded).map(x=>{let f=FOUNDERS[x.founder||'loop'];return `<section class="panel"><div class="eyebrow">${x.failed?'Company closed':x.exit?'Buyer offer':'Your private investment'}</div><h2>${f.name}</h2>${stats([['Ownership',(x.equity*100).toFixed(1)+'%'],['Paper value',money(x.value)],['Weeks invested',x.age]])}<p class="small">${x.failed?'The company failed. Your stake is worth zero.':x.exit?'A buyer offers liquidity, less 3% deal costs.':`Help ${x.support}/3. A round at invested week ${f.round} dilutes you unless you follow; milestone week ${f.milestone}, potential buyer week ${f.exit}.`}</p>${x.failed?'':x.exit?`<div class="actions">${btn('Review cash exit','reviewStartupExit',{id:x.id},'primary')}</div>`:`<div class="actions">${btn(f.help+' · '+money(f.helpCost),'mentor',{id:x.id})}${x.age>=f.round-2&&x.age<=f.round&&!x.followed?btn('Follow round · '+money(f.follow),'follow',{id:x.id}):''}</div>`}</section>`}).join('')}${(s.closedInvestments||[]).map(x=>`<section class="panel"><div class="eyebrow">Exit completed · week ${x.week}</div><h2>${FOUNDERS[x.founder].name}</h2><p>${money(x.proceeds)} cash returned after 3% deal costs. ${x.age} invested weeks; ${(x.equity*100).toFixed(1)}% final ownership.</p><p class="small">This authored founder scenario is closed. Your outcome is saved.</p></section>`).join('')}`;}
function cashHistory(){let history=s.weeklyHistory||[];if(!history.length)return '';let low=Math.min(0,...history.map(h=>h.cash)),high=Math.max(1,...history.map(h=>h.cash)),points=history.map((h,i)=>`${i/Math.max(1,history.length-1)*300},${75-(h.cash-low)/(high-low)*65}`).join(' ');return `<section class="panel"><h3>How your cash is changing</h3><p class="small">Last ${history.length} settled weeks. End-of-week cash includes work and purchases made earlier that week; net cash below is settlement only. A higher paper valuation does not pay bills.</p><svg class="chart cash-history" viewBox="0 0 300 85" role="img" aria-label="End-of-week cash history, ${esc(money(history[0].cash))} to ${esc(money(history.at(-1).cash))}"><polyline fill="none" stroke="#D5A04B" stroke-width="3" points="${points}"/></svg><div class="history-scroll"><table><caption class="small">Most recent settlements</caption><thead><tr><th>Week</th><th>End cash</th><th>Settlement</th><th>Company profit</th></tr></thead><tbody>${history.slice(-8).reverse().map(h=>`<tr><th>${h.week}</th><td>${money(h.cash)}</td><td>${money(h.net)}</td><td>${money(h.operatingProfit)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function cashExposurePanel(plan){if(!s.businesses.length)return '';let q=cashExposure(s,plan);return `<section class="panel cash-exposure ${q.shortfall?'cash-shortfall':''}"><div class="eyebrow">Before you run settlement week ${s.week}</div><h2>${q.shortfall?'Cash falls below zero in this plan':q.afterHeld<0?'Some cash is already spoken for':'Separate cash from commitments'}</h2><dl><div><dt>Cash after forecast settlement</dt><dd class="${q.balance<0?'negative':'positive'}">${money(q.balance)}</dd></div><div><dt>Unpaid wages + premises afterward</dt><dd>${money(q.held)}</dd></div><div><dt>After earmarking those bills</dt><dd class="${q.afterHeld<0?'negative':'positive'}">${money(q.afterHeld)}</dd></div></dl>${q.shortfall?`<p class="cash-warning">Forecast gap ${money(q.shortfall)}. An automatic order's $500 floor does not protect wages, rent or personal bills.</p>`:''}<p class="small">Only the next settlement is forecast. Earmarking is a planning subtraction, not another charge or a claim that these bills are all due next week. Future sales and costs keep changing. Side hustles and dividends are excluded; this is not a solvency guarantee.</p>${q.maintenance.length?`<details><summary>Equipment nearing a capacity loss · ${money(q.maintenanceCost)} to repair now</summary>${q.maintenance.map(b=>`<p class="small">${esc(b.name)} · ${money(b.cost)}. Repair cost is not in the settlement forecast.</p>`).join('')}<button data-nav="business">Inspect equipment →</button></details>`:''}<button data-focus-cash>Review company cash order ↓</button></section>`;}
function portfolioCashOrder(plan){if(!plan.companies.length)return '';return `<section class="panel portfolio-cash-order"><h2>Plan the shared cash</h2><p class="small">Companies settle in the order below. Each manager buys stock using the cash available at that point, keeping $500 before that firm's bills. Customer collections and operating bills then change what the next firm can use. Reordering is free and reversible, but can change stock orders when cash is tight.</p>${plan.companies.map((q,i)=>`<div class="forecast" data-cash-order="${q.id}"><h3>${i+1}. ${esc(q.name)}</h3><div class="rows">${[['Collections',q.collections],['Stock order · '+q.stockOrder+' units',-q.stockCost],['Bills + other operations',-(q.outflow-q.stockCost)],['Company cash change',q.net]].map(([name,value])=>`<div class="split"><span>${name}</span><strong class="num ${value<0?'negative':'positive'}">${money(value)}</strong></div>`).join('')}</div>${plan.companies.length>1?`<div class="actions">${i?btn('Settle earlier','settlementOrder',{id:q.id,direction:-1}):''}${i<plan.companies.length-1?btn('Settle later','settlementOrder',{id:q.id,direction:1}):''}</div>`:''}</div>`).join('')}<p class="small">Portfolio cash forecast ${money(plan.net)}, including personal living costs, property and loan payments. Side hustles and dividends are not forecast here. No new sales or purchases happen until you run the week. Demand, tenants and production can change actual results. Bills can still take cash below $500; this is not a guarantee of solvency.</p>${btn('Run the week','week',{},'primary')}</section>`;}
function books(){let plan=cashPlan(s);return `<main class="main"><div class="section-head"><div><div class="eyebrow">Understand the outcome</div><h1>Books & story</h1><p class="small">${economicState(s).name}: ${economicState(s).desc}</p><p class="small">Next-week bills forecast ${money(plan.outflow)}; collections/rent ${money(plan.collections+plan.rent)}. Excludes manual purchases, side hustles and dividends.</p></div></div>${cashExposurePanel(plan)}${portfolioCashOrder(plan)}${(s.loans||[]).length?`<section class="panel"><h3>Growth loans</h3>${s.loans.map(l=>`<p>${money(l.balance)} remaining · ${money(l.payment)}/week at ${l.rate*100}% annual interest.</p><div class="actions">${btn('Pay off '+money(l.balance),'repayLoan',{id:l.id})}</div>`).join('')}</section>`:''}${s.report?`<section class="panel cream"><div class="eyebrow" style="color:#647c78">Week ${s.report.week} settled</div><h2>${s.report.net>=0?'Cash moving forward':'A week to learn from'}</h2>${stats([['Business sales',money(s.report.revenue)],['Net cash change',money(s.report.net)],['Available now',money(s.cash)]])}<p class="small">Cash change includes operating cash, rents, dividends, carrying costs and living costs. Not consolidated taxable profit.</p></section><section class="panel rows">${s.report.items.map(i=>`<div><div class="split"><strong>${esc(i.name)}</strong><strong class="num ${i.amount<0?'negative':'positive'}">${money(i.amount)}</strong></div><p class="small">${esc(i.why)}</p></div>`).join('')}</section>`:'<section class="panel"><h2>Your first week is unwritten</h2><p>Make a few choices, then run the week to see where the cash went.</p></section>'}${cashHistory()}<div class="grid"><section class="panel"><h3>Your story</h3><div class="rows">${s.events.map(e=>`<div><small>Week ${e.week}</small><h3>${esc(e.title)}</h3><p class="small">${esc(e.body)}</p></div>`).join('')||'<p class="empty">Start with your first customer.</p>'}</div></section><section class="panel"><h3>Cash ledger</h3><div class="rows">${s.ledger.slice(0,25).map(e=>`<div class="split"><div><small>Week ${e.week}</small><p>${esc(e.reason)}</p></div><strong class="num ${e.amount<0?'negative':'positive'}">${money(e.amount)}</strong></div>`).join('')||'<p class="empty">Opening cash $110.</p>'}</div></section></div><p class="footer-note">Playable preview v0.32. Fictional simplified economy, not investment advice or a real-market model. No real money, ads or paid recovery. Full tax, defaults, tenant-level leasing and multiplayer remain build work.</p></main>`;}
function render(){document.body.classList.toggle('owner-room',!!s.life&&s.life.phase==='owner'&&stage(s)<3&&tab==='city');document.body.classList.toggle('life-mode',!!s.life&&s.life.phase!=='owner'&&tab==='city');document.body.classList.toggle('immersive',tab==='city');let scroll=window.scrollY,opened=[...document.querySelectorAll('#app details')].filter(d=>d.open).map(d=>d.querySelector('summary')?.textContent),focus=document.activeElement,focusKey=focus?.matches('button,select')?['action','args','nav','business','founder','dealtab','setting','id'].map(k=>[k,focus.dataset[k]]).filter(([,v])=>v!==undefined):null;$('#app').innerHTML=`<header class="top"><div class="top-inner"><div><div class="eyebrow">Business sim · preview</div><div class="week">Week ${s.week}</div></div><div class="top-actions"><div><div class="small">Available cash</div><div class="cash">${s.life?'$'+s.cash.toFixed(2):money(s.cash)}</div></div><button class="save" id="savebtn">Save</button></div></div></header><div class="stagebar"><strong>${stageName(s)}</strong><span>Net worth ${money(worth(s))}</span>${s.life?.phase==='clicker'?btn('Sleep · next day','life:sleep',{},'weekstep'):btn('Next week','week',{},'weekstep')}</div>${tab==='city'?home():tab==='business'?business():tab==='property'?property():tab==='deals'?deals():books()}<nav class="nav" aria-label="Game sections">${[['city','⌂','Home'],['business','▤','Business'],['property','▥','Property'],['deals','◇','Deals'],['report','≡','Books']].map(([id,icon,name])=>`<button data-nav="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${name}</button>`).join('')}</nav>`;for(let d of document.querySelectorAll('#app details'))if(opened.includes(d.querySelector('summary')?.textContent))d.open=true;if(focusKey?.length){let target=[...document.querySelectorAll('#app button,#app select')].find(el=>focusKey.every(([k,v])=>el.dataset[k]===v));target?.focus({preventScroll:true});}window.scrollTo(0,scroll);$('#savebtn').onclick=()=>window.CloudSave?.openMenu?.();$('#recover-save')?.addEventListener('click',()=>{let raw=localStorage.getItem(KEY+'-recovery');if(!raw)return;let blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='business-sim-damaged-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
function review(type,a){if(type==='reviewRestock'){let b=s.businesses.find(b=>b.id===a.id);if(!b)return;return modal(b.autoRestock?'Stop manager purchases?':'Delegate stock purchases?',`<p>${esc(b.name)} will ${b.autoRestock?'stop buying inventory automatically.':'buy stock at current supplier prices each week, limited to '+money(b.restockBudget||1000)+' and keeping $500 cash before bills. Other bills can still exceed that reserve. Factory production remains a separate manager setting.'}</p>`,{label:b.autoRestock?'Stop restocking':'Delegate restocking',type:'autoRestock',args:a});}let b=s.businesses.find(x=>x.id===a.id);if(type==='reviewOpen'){let k=INDUSTRIES[a.industry];modal('Start '+k.name,`<p>Pay ${money(startupCost(s,a.industry))} now. Weekly overhead ${money(k.overhead)} starts immediately. Recruiting, wages and materials are separate. Keep at least ${money(180+k.wage+k.overhead)} for one employee recruitment and a week of wages/premises, plus any inventory. This is a planning reserve, not an extra purchase fee.</p>`,{label:'Start company',type:'open',args:a});}else if(type==='reviewLoan'){let principal=Math.max(500,Math.min(5000,Math.floor(valuation(s,b)*.15)));modal('Growth loan',`<p>Borrow ${money(principal)} at 12% fixed annual interest, 52 weekly payments of ${money(payment(principal,.12,52))}. Needs a manager and eight settled weeks with positive cumulative operating profit. Debt lowers net worth, and repayments continue even if the company is sold. Early payoff has no added fee in this simulation.</p>`,{label:'Take growth loan',type:'loan',args:a});}else if(type==='reviewOutside'){let offer=Math.round(valuation(s,b)*.25);modal('Bring in an investor',`<p>Receive ${money(offer)} for 20% permanent equity. The investor takes 20% of future positive operating profit and sale proceeds. You keep control but not all the upside.</p>`,{label:'Accept equity investment',type:'outside',args:a});}else if(type==='reviewSale')modal('Sell '+b.name,`<p>Net modeled offer ${money(valuation(s,b))}, including stock/invoices and subtracting accrued wages/premises. No cash buyer if that value is zero or negative. After 5% deal costs, receive ${money(valuation(s,b)*.95*(1-(b.investor||0)))}. The buyer assumes the included stock, invoices and accrued bills. Separate growth loans remain your obligation. The company and all future operating income leave your portfolio. This cannot be undone.</p>`,{label:'Accept sale',type:'sellBusiness',args:a});else if(type==='reviewBranch')modal('Open another location',`<p>Fit-out ${money(INDUSTRIES[b.type].cost*1.3+b.tools*INDUSTRIES[b.type].tool*.6)}. One employee starts there; wages and overhead are separate. Your original manager stays at the first location. Outside equity, if present, also covers this new location.</p>`,{label:'Open branch',type:'branch',args:a});else if(type==='reviewFire')modal('Release an employee','<p>Pay $100 transition compensation. Wages and capacity both fall.</p>',{label:'Release employee',type:'fire',args:a});else if(type==='reviewProperty'){let k=PROPERTIES[a.kind||'apartments'];modal('Buy '+k.name,`<p>${money(k.deposit)} down, ${money(k.loan)} loan, ${(k.rate*100).toFixed(1)}% fixed annual rate, ${k.term} weekly payments of ${money(payment(k.loan,k.rate,k.term))}.</p><p>Initial modeled rent ${money(k.rent*k.occupancy)}/week before ${money(k.maintenance)} maintenance and mortgage. Vacancy, lease turnover and declining condition can reduce rent. Sale costs 6%; debt must be paid off. No real money is involved.</p>`,{label:'Buy with this mortgage',type:'property',args:a});}else if(type==='reviewPropertySale'){let p=s.properties.find(x=>x.id===a.id);modal('Sell property',`<p>Receive ${money(p.value*.94-p.debt)} after 6% selling costs and ${money(p.debt)} loan payoff. You give up its rents.</p>`,{label:'Sell property',type:'sellProperty',args:a});}else if(type==='reviewAcquire'){let f=acquisitionForecast(s);modal('Corner & Co. books',`<p>Asking $6,800, including 100 ingredient units and an established trading history. Two staff cost ${money(f.wages)}/week, premises ${money(f.overhead)}, materials ${money(f.inputPrice)}/sale, price ${money(f.price)}/sale. Equipment/training level 1, condition 70%, no manager.</p><p>Current modeled capacity ${f.capacity} orders/week; demand ${f.demand}; stocked sales ${f.units}. Weekly operating profit ${money(f.profit)} before unsold ingredient spoilage. Forecast at current skills, rivals and events, not promised income. Restocking, maintenance and manager onboarding cost extra.</p>`,{label:'Acquire · $6,800',type:'acquire',args:a});}else if(type==='reviewStartup'){let k=FOUNDERS[a.founder||'loop'];modal('Back '+k.name,`<p>Invest ${money(k.ask)} for ${(a.offer==='negotiate'?k.negotiate:k.equity)*100}%. Money is locked up and can be lost. A later round needs ${money(k.follow)} or dilutes you.</p>`,{label:'Invest '+money(k.ask),type:'startup',args:a});}else if(type==='reviewStartupExit'){let p=s.startups.find(x=>x.id===a.id);modal('Founder exit',`<p>Receive ${money(p.value*.97)} after 3% deal costs. You give up the whole stake.</p>`,{label:'Accept exit',type:'startupExit',args:a});}}
document.addEventListener('click',e=>{if(e.target.closest('[data-focus-cash]')){document.querySelector('.portfolio-cash-order')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}if(e.target.closest('[data-focus-controls]')){document.querySelector('#home-controls')?.scrollIntoView({behavior:'smooth',block:'start'});return;}let sheet=e.target.closest('button[data-life-sheet]');if(sheet){lifeSheet(sheet.dataset.lifeSheet);return;}let n=e.target.closest('[data-nav]');if(n){if(s.life?.phase==='clicker'&&n.dataset.nav!=='city'){toast('Your first full-time job opens the wider game. Jobs and learning are in your room.');return;}tab=n.dataset.nav;if($('#modal').open)$('#modal').close();window.scrollTo(0,0);render();return;}let b=e.target.closest('[data-business]');if(b){chosen=Number(b.dataset.business);render();return;}let f=e.target.closest('[data-founder]');if(f){selectedFounder=f.dataset.founder;render();return;}let d=e.target.closest('[data-dealtab]');if(d){dealTab=d.dataset.dealtab;render();return;}let a=e.target.closest('[data-action]');if(a){let type=a.dataset.action,args=JSON.parse(a.dataset.args||'{}');if(type==='week'&&reviewSettlement())return;if(type==='question'){run('askFounder',args);}else if(type.startsWith('review'))review(type,args);else run(type,args);}});
document.addEventListener('change',e=>{if(e.target.dataset.setting)run(e.target.dataset.setting,{id:Number(e.target.dataset.id),level:Number(e.target.value)});});
let hold,holdPointer=null,held=false,suppressWorkClickUntil=0;function stopHold(){clearTimeout(hold);clearInterval(hold);holdPointer=null;if(held){suppressWorkClickUntil=performance.now()+700;}held=false;}document.addEventListener('click',e=>{if(performance.now()<suppressWorkClickUntil&&e.detail!==0&&e.target.closest('.workbtn')){e.preventDefault();e.stopImmediatePropagation();}},true);document.addEventListener('pointerdown',e=>{if(!e.target.closest('.workbtn')||e.button!==0)return;stopHold();suppressWorkClickUntil=0;holdPointer=e.pointerId;hold=setTimeout(()=>{held=true;if(!run('work')){stopHold();return;}hold=setInterval(()=>{if(s.workThisWeek>=12||!run('work'))stopHold();},220);},450);});for(let event of ['pointerup','pointercancel','visibilitychange'])document.addEventListener(event,stopHold);window.addEventListener('blur',stopHold);document.addEventListener('pointermove',e=>{if(holdPointer===e.pointerId&&!document.elementFromPoint(e.clientX,e.clientY)?.closest('.workbtn'))stopHold();});

render();persist();if(window.CloudSave)CloudSave.initLS({game:'business-tycoon',keys:[KEY],summarize:data=>{try{let x=JSON.parse(data[KEY]||'{}');return `Week ${x.week||1}, ${money(x.cash||0)}, ${(x.businesses||[]).length} companies`;}catch{return 'Invalid save';}},validate:data=>{try{let x=JSON.parse(data[KEY]);return x.version===1&&Number.isFinite(x.cash)&&Array.isArray(x.businesses)&&validSave(x);}catch{return false;}},mount:{none:true}});
